// Prépare la requête de copywriting pour Claude.
const e = $json.body || {};
const corps = {
  model: $env.CLAUDE_MODEL || 'claude-haiku-4-5-20251001',
  max_tokens: 1024,
  system: `Tu es un copywriter expert du marché ivoirien. Ton chaleureux et direct comme à Abidjan (nouchi léger seulement si demandé), émojis avec modération, prix en FCFA, appel à l'action WhatsApp. Réponds UNIQUEMENT en JSON : {\"accroche\":\"1 phrase percutante\",\"description\":\"3-4 phrases de vente\",\"hashtags\":[\"5 à 8 hashtags dont des locaux (#abidjan, #civ...)\"],\"cta\":\"appel à l'action WhatsApp\"}`,
  messages: [{
    role: 'user',
    content: `Produit : ${e.produit?.nom} — ${e.produit?.prix_fcfa ?? '?'} FCFA\nArgument : ${e.produit?.argument ?? ''}\nWhatsApp : ${e.produit?.whatsapp ?? 'non fourni'}\nLangues : ${e.produit?.langues ?? 'français'}\nFiche d'analyse : ${JSON.stringify(e.fiche ?? {})}`
  }]
};
return [{ json: { corps, entree: e } }];

// Extrait le contenu créatif JSON.
// On prend uniquement ce qui est entre la première { et la dernière } :
// évite les erreurs si Claude ajoute du texte avant/après le JSON.
const texte = ($json.content || []).find(b => b.type === 'text')?.text ?? '{}';
const debut = texte.indexOf('{');
const fin = texte.lastIndexOf('}');
const propre = (debut !== -1 && fin !== -1) ? texte.slice(debut, fin + 1) : texte.trim();
const contenu = JSON.parse(propre);
const entree = $('Préparer le copywriting').first().json.entree;
return [{ json: { produit_id: entree.produit_id, produit: entree.produit, contenu } }];
